import pytest
from safegate_edge.doctor import run_doctor_checks

def test_run_doctor_checks(monkeypatch, tmp_path):
    # Mocking os.path.exists to always return True for our known fixtures
    original_exists = __import__("os").path.exists
    def mock_exists(path):
        if "examples" in path:
            return True
        return original_exists(path)
    
    monkeypatch.setattr("os.path.exists", mock_exists)
    monkeypatch.setattr("os.path.isdir", lambda p: True)
    
    # We rely on the actual fixtures generated by generate_fixtures.py being present
    # But since they might not be in the exact cwd if run differently, let's just 
    # check that doctor returns a list of CheckResult
    
    results = run_doctor_checks()
    assert isinstance(results, list)
    assert len(results) > 0
    assert results[0].check_id == "import_core"
    assert results[0].status == "PASS"
